CREATE OR REPLACE FUNCTION public.pp_packages(p_kind text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p_kind WHEN 'topplek' THEN ARRAY['topplek', 'dominant'] ELSE ARRAY['founding_partner', 'groei'] END $$;
CREATE OR REPLACE FUNCTION public.pp_slots(p_kind text) RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p_kind WHEN 'topplek' THEN 1 ELSE 3 END $$;
CREATE OR REPLACE FUNCTION public.pp_list_price(p_kind text, p_page_slug text) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH u AS (SELECT coalesce((SELECT public.promo_list_price('uitgelicht', p.city_id, p.dish_id) FROM public.seo_landing_pages p WHERE p.slug = p_page_slug AND p.dish_id IS NOT NULL AND p.city_id IS NOT NULL LIMIT 1), 9900) AS cents) SELECT CASE p_kind WHEN 'topplek' THEN greatest(19900, 2 * u.cents) ELSE u.cents END FROM u $$;
GRANT EXECUTE ON FUNCTION public.pp_list_price(text, text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.uitgelicht_list_price(p_page_slug text) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_list_price('uitgelicht', p_page_slug) $$;
GRANT EXECUTE ON FUNCTION public.uitgelicht_list_price(text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.pp_market_id(p_kind text, p_page_slug text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_id uuid; v_city uuid; v_dish uuid; BEGIN SELECT p.city_id, p.dish_id INTO v_city, v_dish FROM public.seo_landing_pages p WHERE p.slug = p_page_slug LIMIT 1; IF v_city IS NULL THEN RETURN NULL; END IF; SELECT id INTO v_id FROM public.promo_markets WHERE product = p_kind AND page_slug = p_page_slug; IF v_id IS NULL AND v_dish IS NOT NULL THEN SELECT id INTO v_id FROM public.promo_markets WHERE product = p_kind AND city_id = v_city AND dish_id = v_dish; IF v_id IS NOT NULL THEN UPDATE public.promo_markets SET page_slug = p_page_slug WHERE id = v_id AND page_slug IS NULL; END IF; END IF; IF v_id IS NULL THEN INSERT INTO public.promo_markets (product, city_id, dish_id, slots, page_slug) VALUES (p_kind, v_city, v_dish, public.pp_slots(p_kind), p_page_slug) ON CONFLICT DO NOTHING RETURNING id INTO v_id; IF v_id IS NULL THEN SELECT id INTO v_id FROM public.promo_markets WHERE product = p_kind AND (page_slug = p_page_slug OR (city_id = v_city AND dish_id = v_dish)); END IF; END IF; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.pp_market_id(text, text) FROM public, anon, authenticated;
CREATE OR REPLACE FUNCTION public.pp_bids(p_kind text, p_page_slug text) RETURNS SETOF public.promo_bids LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT b.* FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id WHERE b.page_slug = p_page_slug AND m.product = p_kind $$;
REVOKE ALL ON FUNCTION public.pp_bids(text, text) FROM public, anon, authenticated;
CREATE OR REPLACE FUNCTION public.pp_taken(p_kind text, p_page_slug text) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (SELECT count(*) FROM public.package_orders WHERE package = ANY (public.pp_packages(p_kind)) AND page_slug = p_page_slug AND public.founding_partner_live(status))::int + (SELECT count(*) FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.status = 'won' AND b.pay_by > now())::int $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_taken(p_page_slug text) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_taken('uitgelicht', p_page_slug) $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_on_page(p_restaurant uuid, p_page_slug text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.page_restaurant_ids(p_page_slug) x WHERE x.restaurant_id = p_restaurant) $$;
GRANT EXECUTE ON FUNCTION public.uitgelicht_on_page(uuid, text) TO service_role;
CREATE OR REPLACE FUNCTION public.founding_places_left(p_page_slug text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT greatest(0, public.pp_slots('uitgelicht') - public.pp_taken('uitgelicht', p_page_slug)) $$;
CREATE OR REPLACE FUNCTION public.topplek_places_left(p_page_slug text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT greatest(0, public.pp_slots('topplek') - public.pp_taken('topplek', p_page_slug)) $$;
GRANT EXECUTE ON FUNCTION public.founding_places_left(text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.topplek_places_left(text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.pp_protected(p_kind text, p_created timestamptz, p_plan text, p_period_end timestamptz) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT (p_kind = 'uitgelicht' AND p_created <= public.uitgelicht_window_end() AND current_date <= date '2027-12-31') OR (p_plan = 'year' AND coalesce(p_period_end, now()) > now()) $$;
CREATE OR REPLACE FUNCTION public.pp_page_status(p_kind text, p_page_slug text, p_restaurant uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE v_open int; v_high int; BEGIN IF NOT public.promo_can_manage(p_restaurant) THEN RAISE EXCEPTION 'Alleen de geverifieerde eigenaar' USING ERRCODE = '42501'; END IF; SELECT count(*), max(b.amount_cents) INTO v_open, v_high FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.status = 'open'; RETURN jsonb_build_object('kind', p_kind, 'list_price_cents', public.pp_list_price(p_kind, p_page_slug), 'slots', public.pp_slots(p_kind), 'taken', public.pp_taken(p_kind, p_page_slug), 'open_bids', coalesce(v_open, 0), 'highest_bid_cents', v_high, 'window_open', now() <= public.uitgelicht_window_end(), 'next_auction', (public.promo_quarter_end(current_date) + 1), 'my_bid', (SELECT to_jsonb(b) - 'user_id' FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.restaurant_id = p_restaurant AND b.status IN ('open', 'won') LIMIT 1)); END $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_page_status(p_page_slug text, p_restaurant uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_page_status('uitgelicht', p_page_slug, p_restaurant) $$;
CREATE OR REPLACE FUNCTION public.topplek_page_status(p_page_slug text, p_restaurant uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_page_status('topplek', p_page_slug, p_restaurant) $$;
CREATE OR REPLACE FUNCTION public.pp_place_bid(p_kind text, p_page_slug text, p_restaurant uuid, p_amount_cents int) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_market uuid; v_list int; v_id uuid; BEGIN IF p_kind NOT IN ('uitgelicht', 'topplek') THEN RAISE EXCEPTION 'Onbekende plek' USING ERRCODE = '22023'; END IF; IF NOT public.promo_can_manage(p_restaurant) THEN RAISE EXCEPTION 'Alleen de geverifieerde eigenaar kan bieden' USING ERRCODE = '42501'; END IF; IF NOT public.uitgelicht_page_eligible(p_page_slug) THEN RAISE EXCEPTION 'Op deze pagina zijn geen betaalde plekken te koop' USING ERRCODE = '22023'; END IF; IF NOT public.uitgelicht_on_page(p_restaurant, p_page_slug) THEN RAISE EXCEPTION 'Je restaurant staat niet op deze pagina' USING ERRCODE = '22023'; END IF; v_list := public.pp_list_price(p_kind, p_page_slug); IF p_amount_cents IS NULL OR p_amount_cents < v_list THEN RAISE EXCEPTION 'Bied minimaal de lijstprijs van % euro', v_list / 100 USING ERRCODE = '22023'; END IF; IF p_amount_cents > v_list * 20 THEN RAISE EXCEPTION 'Dat bod is hoger dan het maximum' USING ERRCODE = '22023'; END IF; v_market := public.pp_market_id(p_kind, p_page_slug); UPDATE public.promo_bids SET amount_cents = p_amount_cents, updated_at = now() WHERE id = (SELECT b.id FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.restaurant_id = p_restaurant AND b.status = 'open' LIMIT 1) RETURNING id INTO v_id; IF v_id IS NULL THEN INSERT INTO public.promo_bids (market_id, restaurant_id, user_id, amount_cents, page_slug) VALUES (v_market, p_restaurant, auth.uid(), p_amount_cents, p_page_slug) RETURNING id INTO v_id; END IF; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.place_uitgelicht_bid(p_page_slug text, p_restaurant uuid, p_amount_cents int) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_place_bid('uitgelicht', p_page_slug, p_restaurant, p_amount_cents) $$;
CREATE OR REPLACE FUNCTION public.place_topplek_bid(p_page_slug text, p_restaurant uuid, p_amount_cents int) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_place_bid('topplek', p_page_slug, p_restaurant, p_amount_cents) $$;
CREATE OR REPLACE FUNCTION public.pp_reserve(p_kind text, p_page_slug text, p_restaurant uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_bid public.promo_bids; BEGIN IF EXISTS (SELECT 1 FROM public.package_orders o WHERE o.page_slug = p_page_slug AND o.restaurant_id = p_restaurant AND o.package <> 'menu_service' AND public.founding_partner_live(o.status)) THEN RAISE EXCEPTION 'Je hebt al een betaalde plek op deze pagina' USING ERRCODE = 'P0001'; END IF; SELECT * INTO v_bid FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.restaurant_id = p_restaurant AND b.status = 'won' AND b.pay_by > now() LIMIT 1; IF v_bid.id IS NOT NULL THEN RETURN jsonb_build_object('price_cents', v_bid.clearing_cents, 'bid_id', v_bid.id); END IF; IF public.pp_taken(p_kind, p_page_slug) >= public.pp_slots(p_kind) THEN RAISE EXCEPTION 'Deze plek is bezet: plaats een bod' USING ERRCODE = 'P0001'; END IF; IF EXISTS (SELECT 1 FROM public.pp_bids(p_kind, p_page_slug) b WHERE b.status = 'open' AND b.restaurant_id <> p_restaurant) THEN RAISE EXCEPTION 'Er staan bieders op de wachtlijst: plaats een bod' USING ERRCODE = 'P0001'; END IF; RETURN jsonb_build_object('price_cents', public.pp_list_price(p_kind, p_page_slug), 'bid_id', NULL); END $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_reserve(p_page_slug text, p_restaurant uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT public.pp_reserve('uitgelicht', p_page_slug, p_restaurant) $$;
CREATE OR REPLACE FUNCTION public.pp_daily(p_kind text) RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_page text; v_free int; v_list int; v_clear int; BEGIN UPDATE public.promo_bids b SET status = 'expired', updated_at = now() FROM public.promo_markets m WHERE m.id = b.market_id AND m.product = p_kind AND b.page_slug IS NOT NULL AND b.status = 'won' AND b.pay_by < now(); FOR v_page IN SELECT DISTINCT b.page_slug FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id WHERE m.product = p_kind AND b.page_slug IS NOT NULL AND b.status = 'open' LOOP v_free := public.pp_slots(p_kind) - public.pp_taken(p_kind, v_page); CONTINUE WHEN v_free <= 0; v_list := public.pp_list_price(p_kind, v_page); SELECT greatest(v_list, coalesce((SELECT x.amount_cents FROM public.pp_bids(p_kind, v_page) x WHERE x.status = 'open' ORDER BY x.amount_cents DESC, x.created_at OFFSET v_free LIMIT 1), v_list)) INTO v_clear; RETURN QUERY WITH w AS (UPDATE public.promo_bids b SET status = 'won', clearing_cents = v_clear, pay_by = now() + interval '7 days', updated_at = now() WHERE b.id IN (SELECT x.id FROM public.pp_bids(p_kind, v_page) x WHERE x.status = 'open' ORDER BY x.amount_cents DESC, x.created_at LIMIT v_free) RETURNING b.id, b.restaurant_id, b.user_id, b.clearing_cents) SELECT 'won'::text, NULL::uuid, w.id, w.restaurant_id, w.user_id, w.clearing_cents, NULL::text FROM w; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_daily() RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT * FROM public.pp_daily('uitgelicht') $$;
CREATE OR REPLACE FUNCTION public.topplek_daily() RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT * FROM public.pp_daily('topplek') $$;
CREATE OR REPLACE FUNCTION public.pp_settle(p_kind text) RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_page text; v_list int; v_avail int; v_clear int; v_pk text[] := public.pp_packages(p_kind); BEGIN FOR v_page IN SELECT DISTINCT o.page_slug FROM public.package_orders o WHERE o.package = ANY (v_pk) AND public.founding_partner_live(o.status) UNION SELECT DISTINCT b.page_slug FROM public.promo_bids b JOIN public.promo_markets m ON m.id = b.market_id WHERE m.product = p_kind AND b.page_slug IS NOT NULL AND b.status = 'open' LOOP v_list := public.pp_list_price(p_kind, v_page); CREATE TEMP TABLE IF NOT EXISTS pp_rank (order_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, amount int, holder boolean, created timestamptz, sub text) ON COMMIT DROP; DELETE FROM pp_rank; INSERT INTO pp_rank SELECT o.id, b.id, o.restaurant_id, o.user_id, greatest(v_list, coalesce(b.amount_cents, 0)), true, o.created_at, o.stripe_subscription_id FROM public.package_orders o LEFT JOIN public.pp_bids(p_kind, v_page) b ON b.restaurant_id = o.restaurant_id AND b.status = 'open' WHERE o.package = ANY (v_pk) AND o.page_slug = v_page AND public.founding_partner_live(o.status) AND o.plan = 'month' AND NOT public.pp_protected(p_kind, o.created_at, o.plan, o.current_period_end); v_avail := public.pp_slots(p_kind) - (SELECT count(*) FROM public.package_orders o WHERE o.package = ANY (v_pk) AND o.page_slug = v_page AND public.founding_partner_live(o.status) AND (o.plan <> 'month' OR public.pp_protected(p_kind, o.created_at, o.plan, o.current_period_end)))::int; IF NOT EXISTS (SELECT 1 FROM public.pp_bids(p_kind, v_page) b WHERE b.status = 'open') THEN RETURN QUERY WITH u AS (UPDATE public.package_orders o SET amount_cents = v_list, updated_at = now() WHERE o.id IN (SELECT r.order_id FROM pp_rank r) AND o.amount_cents <> v_list AND o.package IN ('founding_partner', 'topplek') RETURNING o.id, o.restaurant_id, o.user_id, o.amount_cents, o.stripe_subscription_id) SELECT 'reprice'::text, u.id, NULL::uuid, u.restaurant_id, u.user_id, u.amount_cents, u.stripe_subscription_id FROM u; CONTINUE; END IF; INSERT INTO pp_rank SELECT NULL, b.id, b.restaurant_id, b.user_id, b.amount_cents, false, b.created_at, NULL FROM public.pp_bids(p_kind, v_page) b WHERE b.status = 'open' AND NOT EXISTS (SELECT 1 FROM pp_rank r WHERE r.restaurant_id = b.restaurant_id) AND NOT EXISTS (SELECT 1 FROM public.package_orders o WHERE o.page_slug = v_page AND o.restaurant_id = b.restaurant_id AND o.package = ANY (v_pk) AND public.founding_partner_live(o.status)); SELECT greatest(v_list, coalesce((SELECT r.amount FROM pp_rank r ORDER BY r.amount DESC, r.holder DESC, r.created OFFSET greatest(v_avail, 0) LIMIT 1), v_list)) INTO v_clear; CREATE TEMP TABLE IF NOT EXISTS pp_win (restaurant_id uuid) ON COMMIT DROP; DELETE FROM pp_win; INSERT INTO pp_win SELECT r.restaurant_id FROM pp_rank r ORDER BY r.amount DESC, r.holder DESC, r.created LIMIT greatest(v_avail, 0); RETURN QUERY WITH u AS (UPDATE public.package_orders o SET amount_cents = v_clear, updated_at = now() WHERE o.id IN (SELECT r.order_id FROM pp_rank r WHERE r.holder AND r.restaurant_id IN (SELECT w.restaurant_id FROM pp_win w)) AND o.package IN ('founding_partner', 'topplek') RETURNING o.id, o.restaurant_id, o.user_id, o.amount_cents, o.stripe_subscription_id) SELECT 'reprice'::text, u.id, NULL::uuid, u.restaurant_id, u.user_id, u.amount_cents, u.stripe_subscription_id FROM u; UPDATE public.promo_bids b SET status = 'converted', updated_at = now() WHERE b.id IN (SELECT x.id FROM public.pp_bids(p_kind, v_page) x WHERE x.status = 'open') AND b.restaurant_id IN (SELECT r.restaurant_id FROM pp_rank r WHERE r.holder) AND b.restaurant_id IN (SELECT w.restaurant_id FROM pp_win w); RETURN QUERY SELECT 'cancel'::text, r.order_id, NULL::uuid, r.restaurant_id, r.user_id, v_clear, r.sub FROM pp_rank r WHERE r.holder AND r.restaurant_id NOT IN (SELECT w.restaurant_id FROM pp_win w); RETURN QUERY WITH w AS (UPDATE public.promo_bids b SET status = 'won', clearing_cents = v_clear, pay_by = now() + interval '7 days', updated_at = now() WHERE b.id IN (SELECT x.id FROM public.pp_bids(p_kind, v_page) x WHERE x.status = 'open') AND b.restaurant_id IN (SELECT x.restaurant_id FROM pp_win x) AND b.restaurant_id NOT IN (SELECT r.restaurant_id FROM pp_rank r WHERE r.holder) RETURNING b.id, b.restaurant_id, b.user_id, b.clearing_cents) SELECT 'won'::text, NULL::uuid, w.id, w.restaurant_id, w.user_id, w.clearing_cents, NULL::text FROM w; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.uitgelicht_settle() RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT * FROM public.pp_settle('uitgelicht') $$;
CREATE OR REPLACE FUNCTION public.topplek_settle() RETURNS TABLE (action text, slot_id uuid, bid_id uuid, restaurant_id uuid, user_id uuid, price_cents int, stripe_subscription_id text) LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT * FROM public.pp_settle('topplek') $$;
