GRANT EXECUTE ON FUNCTION public.pp_reserve(text, text, uuid), public.pp_market_id(text, text), public.pp_bids(text, text), public.pp_daily(text), public.pp_settle(text), public.uitgelicht_reserve(text, uuid), public.uitgelicht_daily(), public.uitgelicht_settle(), public.topplek_daily(), public.topplek_settle() TO service_role;